import re
import urllib.request
import urllib.parse
import json
import base64
import time
from fastapi.responses import HTMLResponse
from typing import Optional
from pydantic import BaseModel, Field


class Tools:
    class Valves(BaseModel):
        SPOTIFY_CLIENT_ID: str = Field(
            default="",
            description="Optional: Spotify App Client ID. Highly recommended for accurate Podcasts and 'Vibe' Playlists.",
        )
        SPOTIFY_CLIENT_SECRET: str = Field(
            default="", description="Optional: Spotify App Client Secret."
        )

    def __init__(self):
        self.valves = self.Valves()
        self.spotify_pattern = re.compile(
            r"(?:\[.*?\]\()?(https?://open\.spotify\.com/(track|album|playlist|artist|episode|show)/([a-zA-Z0-9]+))(?:\))?"
        )
        self._access_token = None
        self._token_expires_at = 0

    def _get_spotify_token(self) -> Optional[str]:
        """Authenticates with Spotify using Client Credentials flow if keys are provided."""
        if not self.valves.SPOTIFY_CLIENT_ID or not self.valves.SPOTIFY_CLIENT_SECRET:
            return None

        if self._access_token and time.time() < self._token_expires_at:
            return self._access_token

        auth_string = (
            f"{self.valves.SPOTIFY_CLIENT_ID}:{self.valves.SPOTIFY_CLIENT_SECRET}"
        )
        auth_base64 = base64.b64encode(auth_string.encode("utf-8")).decode("utf-8")

        url = "https://accounts.spotify.com/api/token"
        headers = {
            "Authorization": f"Basic {auth_base64}",
            "Content-Type": "application/x-www-form-urlencoded",
        }
        data = urllib.parse.urlencode({"grant_type": "client_credentials"}).encode(
            "utf-8"
        )

        try:
            req = urllib.request.Request(url, data=data, headers=headers)
            with urllib.request.urlopen(req, timeout=5) as response:
                res_data = json.loads(response.read().decode("utf-8"))
                self._access_token = res_data.get("access_token")
                self._token_expires_at = (
                    time.time() + res_data.get("expires_in", 3600) - 60
                )
                return self._access_token
        except Exception as e:
            print(f"Spotify token generation error: {e}")
            return None

    def _search_spotify_api(self, query: str, search_type: str) -> Optional[str]:
        """Uses the official Spotify API for highly accurate results (Podcasts, Playlists, etc)."""
        token = self._get_spotify_token()
        if not token:
            return None

        url = f"https://api.spotify.com/v1/search?q={urllib.parse.quote(query)}&type={search_type}&limit=1"
        headers = {"Authorization": f"Bearer {token}"}

        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=5) as response:
                data = json.loads(response.read().decode("utf-8"))

                # Spotify pluralizes the response keys (e.g., 'track' -> 'tracks')
                key = search_type + "s"
                items = data.get(key, {}).get("items", [])

                if items and len(items) > 0:
                    item_id = items[0].get("id")
                    if item_id:
                        return f"https://open.spotify.com/{search_type}/{item_id}"
        except Exception as e:
            print(f"Spotify API search error: {e}")

        return None

    def _search_spotify_fallback(self, query: str, search_type: str) -> Optional[str]:
        """Performs a lightweight web search fallback if API keys aren't provided."""
        stype_filter = (
            f"site:open.spotify.com/{search_type}"
            if search_type
            else "site:open.spotify.com"
        )
        search_query = f"{stype_filter} {query}"

        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
        }

        # Primary Fallback: DuckDuckGo HTML
        ddg_url = (
            f"https://html.duckduckgo.com/html/?q={urllib.parse.quote(search_query)}"
        )
        try:
            req = urllib.request.Request(ddg_url, headers=headers)
            with urllib.request.urlopen(req, timeout=5) as response:
                html = urllib.parse.unquote(
                    response.read().decode("utf-8", errors="ignore")
                )
                match = self.spotify_pattern.search(html)
                if match:
                    return match.group(1)
        except Exception:
            pass

        # Secondary Fallback: Yahoo Search
        yahoo_url = (
            f"https://search.yahoo.com/search?p={urllib.parse.quote(search_query)}"
        )
        try:
            req = urllib.request.Request(yahoo_url, headers=headers)
            with urllib.request.urlopen(req, timeout=5) as response:
                html = urllib.parse.unquote(
                    response.read().decode("utf-8", errors="ignore")
                )
                match = self.spotify_pattern.search(html)
                if match:
                    return match.group(1)
        except Exception as e:
            print(f"Spotify tool fallback search error: {e}")

        return None

    def play_spotify_media(
        self, query_or_url: str, search_type: str = "track"
    ) -> tuple[Optional[HTMLResponse], str]:
        """
        Explore a new way to discover music and podcasts. Use this tool to play songs, artists, genres, podcasts, or vibe playlists directly in chat.

        INSTRUCTIONS FOR LLM (ACT LIKE THE SPOTIFY CONNECTOR):
        - If the user asks for a specific song, set search_type="track".
        - If the user asks for a podcast or topic to explore, set search_type="show" or "episode".
        - If the user describes a vibe (e.g. "power my next run", "late night study session"), set search_type="playlist" and summarize the vibe in the query.
        - If the user asks for recommendations based on history, summarize their music taste into a query and search for it.

        :param query_or_url: A direct Spotify URL, OR a search query (e.g., "Daft Punk", "Huberman podcast", "chill workout vibes").
        :param search_type: Choose ONE of: "track", "artist", "playlist", "album", "show", "episode".
        """
        # Step 1: Check if the input already contains a Spotify URL
        match = self.spotify_pattern.search(query_or_url)
        url_to_embed = None

        if match:
            url_to_embed = match.group(1)
            media_type = match.group(2)
            media_id = match.group(3)
        else:
            # Step 2: Validate search_type
            valid_types = ["track", "album", "artist", "playlist", "show", "episode"]
            stype = search_type if search_type in valid_types else "track"

            # Step 3: Try API first, then Fallback Scraper
            url_to_embed = self._search_spotify_api(query_or_url, stype)
            if not url_to_embed:
                url_to_embed = self._search_spotify_fallback(query_or_url, stype)

            if not url_to_embed:
                return (
                    None,
                    f"System Error: Could not find a valid Spotify link for '{query_or_url}'. Please inform the user gracefully.",
                )

            # Re-match to safely extract media_type and media_id from the found URL
            match = self.spotify_pattern.search(url_to_embed)
            if not match:
                return (
                    None,
                    f"System Error: Failed to parse the resolved Spotify URL: '{url_to_embed}'. Please inform the user gracefully.",
                )

            media_type = match.group(2)
            media_id = match.group(3)

        # theme=0 enforces the dark theme used by Discord.
        embed_url = f"https://open.spotify.com/embed/{media_type}/{media_id}?utm_source=generator&theme=0"

        # Construct a self-contained HTML document.
        html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body, html {{
            margin: 0;
            padding: 0;
            background-color: transparent; 
            display: flex;
            justify-content: flex-start;
            overflow: hidden;
            height: 352px;
        }}
        .discord-spotify-wrapper {{
            width: 400px;
            max-width: 100%;
            height: 352px;
            border-radius: 12px;
            overflow: hidden;
        }}
        iframe {{
            border: none;
            width: 100%;
            height: 100%;
            background-color: transparent;
        }}
    </style>
</head>
<body>
    <div class="discord-spotify-wrapper">
        <iframe src="{embed_url}" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>
    </div>
</body>
</html>"""

        headers = {"Content-Disposition": "inline"}
        response = HTMLResponse(content=html_content, headers=headers)

        # Explicit, directive context for the LLM to prevent hallucinations / apologies.
        context_for_llm = (
            f"ACTION SUCCESSFUL: You have successfully embedded a playable Spotify {media_type} widget for '{query_or_url}'. "
            f"The URL embedded is {url_to_embed}. "
            f"IMPORTANT INSTRUCTION: The widget is already visually rendered on the user's screen. "
            f"Do NOT apologize or say you lack information. "
            f"Simply provide a short, cool, and friendly confirmation that you have dropped the right music or podcast into the chat."
        )

        return response, context_for_llm
